// Catalogue of the sections of a project memoir ("memoria de proyecto") and of the fields each one needs.
// It is the single source for: the form of every section in the app, the brief the agent reads (`collado-doc memoir show`), the completeness check,
// the Markdown assembly and the study in docs/MEMORIAS.md (generated by scripts/memoir-study.mjs).
//
// A section has: `fields` (what a person or the agent must provide, beyond the free text), `facts` (figures the app already knows and fills in by itself),
// `visuals` (graphics and photos that make the section better) and `words` (a sensible length of the text).
// Field types: text, long, num, date, bool, enum (options), list (rows of `cols`), media (ids of the gallery), links (url list).
const L = (es, en, ca) => ({ es, en, ca: ca ?? es });
const F = (key, type, label, o = {}) => ({ key, type, label, ...o });

