/** Section order and default selection per kind of memoir. */
export const ORDER = Object.keys(SECTIONS);
export const defaultSections = (kind) => ORDER.filter((k) => SECTIONS[k].kinds.includes(KINDS.includes(kind) ? kind : "annual"));

const pick = (o, lang) => (o && typeof o === "object" ? o[lang] ?? o.es : o);
const field = (f, lang) => ({ key: f.key, type: f.type, label: pick(f.label, lang), required: !!f.required, ...(f.options ? { options: f.options } : {}), ...(f.cols ? { cols: f.cols.map((c) => field(c, lang)) } : {}), ...(f.max ? { max: f.max } : {}) });
/** The catalogue as the app and the agent read it: labels resolved to one language. */
export function catalog(lang = "es") {
  return { kinds: KINDS.map((k) => ({ key: k, label: pick(KIND_LABEL[k], lang), sections: defaultSections(k) })),
    sections: ORDER.map((k) => { const s = SECTIONS[k]; return { key: k, title: pick(s.title, lang), purpose: pick(s.purpose, lang), words: s.words, visual: !!s.visual, facts: s.facts, visuals: s.visuals, kinds: s.kinds, perm: s.perm || null, fields: s.fields.map((f) => field(f, lang)) }; }) };
}
export const sectionTitle = (key, lang = "es") => pick(SECTIONS[key]?.title, lang) || key;

/** Share of the required material present: required fields filled (list = at least one non-empty row), text with at least `min` words. Returns { pct, missing:[...] }. */
export function completeness(key, section) {
  const def = SECTIONS[key]; if (!def) return { pct: 0, missing: [] };
  const body = String(section?.body || "").trim(), words = body ? body.split(/\s+/).length : 0, fields = section?.fields || {}, missing = [];
  const filled = (f, v) => (f.type === "list" ? Array.isArray(v) && v.some((r) => r && Object.values(r).some((x) => String(x ?? "").trim())) : f.type === "media" ? Array.isArray(v) && v.length > 0 : v !== undefined && v !== null && String(v).trim() !== "");
  const required = def.fields.filter((f) => f.required);
  for (const f of required) if (!filled(f, fields[f.key])) missing.push({ kind: "field", key: f.key });
  const min = def.words[0]; if (min && words < Math.ceil(min * 0.6)) missing.push({ kind: "text", have: words, need: min });
  const total = required.length + (min ? 1 : 0); if (!total) return { pct: section?.status === "empty" || (!body && !Object.keys(fields).length) ? 0 : 100, missing };
  return { pct: Math.round(((total - missing.length) / total) * 100), missing };
}
